/**
 * SAMPLE throne history for demo mode. Every listing is fictional (reserved .example domains) and flagged
 * sample:true. The history is generated by replaying real takes through the rules, so every price paid and
 * every reign length is consistent with how the Throne actually works.
 */
import type { Listing } from "@/lib/board/types";
import { HOUR_MS, INITIAL_DATA, applyTake, priceAt } from "./rules";
import type { ThroneData } from "./types";

const DAY = 24 * HOUR_MS;

const SAMPLE_LISTINGS: Omit<Listing, "createdAt" | "verified" | "sample">[] = [
  { domain: "northwind-studio.example", name: "Northwind Studio (sample)", url: "https://northwind-studio.example", category: "Marketing", tagline: "Short-form video ads for apps" },
  { domain: "harborlane-media.example", name: "Harbor Lane Media (sample)", url: "https://harborlane-media.example", category: "Agents", tagline: "Newsletter sponsorships, booked fast" },
  { domain: "pinewood-analytics.example", name: "Pinewood Analytics (sample)", url: "https://pinewood-analytics.example", category: "Developer", tagline: "Attribution reports without the spreadsheet" },
  { domain: "copperfield-creative.example", name: "Copperfield Creative (sample)", url: "https://copperfield-creative.example", category: "Marketing", tagline: "Paid social creative sprints" },
  { domain: "lumenloop.example", name: "Lumen Loop (sample)", url: "https://lumenloop.example", category: "SEO", tagline: "Creative testing in one dashboard" },
  { domain: "tidewater-goods.example", name: "Tidewater Goods (sample)", url: "https://tidewater-goods.example", category: "Productivity", tagline: "Small-batch home goods" },
  { domain: "marigold-pod.example", name: "Marigold Podcasts (sample)", url: "https://marigold-pod.example", category: "Crypto", tagline: "Podcast ads that get heard" },
  { domain: "quartzco.example", name: "Quartz & Co (sample)", url: "https://quartzco.example", category: "Games", tagline: "Brand naming on a deadline" },
];

/** [listing index, hours held before the next take], oldest first. The final reign is ongoing. */
const SCRIPT: readonly (readonly [number, number])[] = [
  [0, 6], [1, 3.5], [2, 14], [3, 1.25], [0, 9], [4, 20], [5, 2], [1, 7.5], [6, 4], [2, 11], [7, 0.8],
];
const ONGOING: readonly [number, number] = [3, 3.2];

export function buildSeed(now: number): ThroneData {
  const listings: Listing[] = SAMPLE_LISTINGS.map((l, i) => ({ ...l, createdAt: now - (40 + i) * DAY, verified: false, sample: true }));
  const holds = [...SCRIPT.map((s) => s[1]), ONGOING[1]];
  const total = holds.reduce((a, b) => a + b, 0);
  let at = now - Math.round(total * HOUR_MS);
  let data: ThroneData = INITIAL_DATA;
  [...SCRIPT, ONGOING].forEach(([idx], i) => {
    const decision = applyTake(
      data,
      { listing: listings[idx], expectedPriceCents: priceAt(data.state, at) },
      at,
      `sample_${i + 1}`,
      { sample: true },
    );
    if (decision.ok) data = decision.data;
    at += Math.round(holds[i] * HOUR_MS);
  });
  return data;
}
